// Tree helpers (generated by engineering-platform frontend-enterprise-management asset)
import type { DepartmentNode, Department, MenuNode, Menu } from '../types/enterprise';

export function flattenDepartments(nodes: DepartmentNode[]): Department[] {
  const result: Department[] = [];
  const walk = (list: DepartmentNode[]): void => {
    for (const node of list) {
      result.push(node.department);
      walk(node.children);
    }
  };
  walk(nodes);
  return result;
}

export function flattenMenus(nodes: MenuNode[]): Menu[] {
  const result: Menu[] = [];
  const walk = (list: MenuNode[]): void => {
    for (const node of list) {
      result.push(node.menu);
      walk(node.children);
    }
  };
  walk(nodes);
  return result;
}
